import{_ as s,C as r,c as o,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const v=JSON.parse('{"title":"Preventive maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/requests/preventive-maintenance.md","filePath":"master/supply-chain/maintenance/requests/preventive-maintenance.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/maintenance/requests/preventive-maintenance.md"};function h(c,e,p,d,u,g){const n=r("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=t('<h1 id="preventive-maintenance" tabindex="-1">Preventive maintenance <a class="header-anchor" href="#preventive-maintenance" aria-label="Permalink to &quot;Preventive maintenance&quot;">​</a></h1><p>Preventive maintenance is planned work that stops a machine from breaking. You service it on a schedule, such as greasing every month. A preventive request can repeat on its own, so you create it once and Aureus makes the next one each time you finish.</p><blockquote><p><strong>In simple words:</strong> Set the request to repeat. When you close one, the next one appears with a new date.</p></blockquote><p>Open <code>Maintenance → Maintenance Requests</code> and click <strong>New Maintenance Request</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>You need a <a href="./../setup/maintenance-teams.html">team</a>, <a href="./../setup/stages.html">stages</a> and <a href="./../equipment/add-equipment.html">equipment</a>. Read <a href="./create-request.html">Create a maintenance request</a> for the main form.</p></div><h2 id="make-a-request-repeat" tabindex="-1">Make a request repeat <a class="header-anchor" href="#make-a-request-repeat" aria-label="Permalink to &quot;Make a request repeat&quot;">​</a></h2><p>The example is <strong>Monthly lubrication, Hydraulic Press 200T</strong>. It must happen once a month.</p><ol><li>Type <strong>Monthly lubrication, Hydraulic Press 200T</strong> in <strong>Request</strong>.</li><li>Choose <strong>Hydraulic Press 200T</strong> in <strong>Equipment</strong>.</li><li>Under <strong>Maintenance Type</strong>, click <strong>Preventive</strong>. A <strong>Recurrent</strong> checkbox appears.</li></ol>',8)),a(n,{src:"/images1/maintenance/prev_type_preventive.png",alt:"Monthly lubrication request with Maintenance Type set to Preventive and the Recurrent checkbox visible"}),e[1]||(e[1]=t('<ol start="4"><li>Tick <strong>Recurrent</strong>. The <strong>Repeat Every</strong> field appears.</li><li>Type <strong>1</strong> in the number box. Choose <strong>Months</strong> in the unit list. Leave the last list on <strong>Forever</strong>.</li></ol>',1)),a(n,{src:"/images1/maintenance/prev_repeat_every.png",alt:"Repeat Every set to 1 Months Forever on the Hydraulic Press 200T request"}),e[2]||(e[2]=t('<ol start="6"><li>In <strong>Settings</strong>, set <strong>Scheduled Date</strong> to <code>Oct 20, 2026 09:00</code> and <strong>Duration</strong> to <code>01:00</code>. This date starts the cycle.</li><li>Click <strong>Create</strong>. You land on the <strong>View</strong> page of the request.</li></ol>',1)),a(n,{src:"/images1/maintenance/prev_filled_request.png",alt:"Completed Monthly lubrication request with Preventive, Recurrent, Repeat Every 1 Months Forever, scheduled Oct 20, 2026 09:00"}),e[3]||(e[3]=t('<ul><li><strong><em>Recurrent:</em></strong> Tick it to repeat the job. It shows only for <strong>Preventive</strong>. If you switch back to <strong>Corrective</strong>, the box disappears and is cleared.</li><li><strong><em>Repeat Every:</em></strong> Required. A whole number of at least 1.</li><li><strong>Unit:</strong> <strong>Days</strong>, <strong>Weeks</strong>, <strong>Months</strong> or <strong>Years</strong>. The default is <strong>Weeks</strong>.</li><li><strong>Forever:</strong> The request repeats without an end. This is the default.</li></ul><h2 id="what-happens-when-you-close-it" tabindex="-1">What happens when you close it <a class="header-anchor" href="#what-happens-when-you-close-it" aria-label="Permalink to &quot;What happens when you close it&quot;">​</a></h2><p>The request repeats when you save it in a stage with the <strong>Done</strong> flag, such as <strong>Repaired</strong>.</p><ol><li>A technician finishes the job, chooses <strong>Repaired</strong> on the <strong>Edit</strong> page and clicks <strong>Save changes</strong>. See <a href="./process-request.html">Process a request</a>.</li><li>Aureus makes a copy in the first stage, <strong>New Request</strong>.</li><li>The copy has a new <strong>Scheduled Date</strong>: the original date plus the interval. It keeps the time and duration.</li><li>An activity is created for the <strong>Responsible</strong> person on the copy.</li></ol><h3 id="dates-in-the-example" tabindex="-1">Dates in the example <a class="header-anchor" href="#dates-in-the-example" aria-label="Permalink to &quot;Dates in the example&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Step</th><th>Scheduled Date</th></tr></thead><tbody><tr><td>First request, scheduled</td><td>20 Oct 2026 09:00</td></tr><tr><td>You save it in <strong>Repaired</strong></td><td></td></tr><tr><td>Copy appears in <strong>New Request</strong></td><td>20 Nov 2026 09:00</td></tr><tr><td>You save the copy in <strong>Repaired</strong>, and the next copy appears</td><td>20 Dec 2026 09:00</td></tr></tbody></table><p>The new date is the old <strong>Scheduled Date</strong> plus the interval, not today plus the interval. Closing late does not shift the cycle.</p>',7)),a(n,{src:"/images1/maintenance/prev_copy_created.png",alt:"Request list showing the Repaired Monthly lubrication request for 20 Oct 2026 and its new copy in New Request for 20 Nov 2026"}),e[4]||(e[4]=t('<h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>The copy keeps the same equipment, team, responsible person, duration, priority, notes and instructions. The activity for the copy appears in the request&#39;s <a href="./../../../getting-started/chatter.html">Chatter</a> and in <a href="./../../../getting-started/activities.html">Activities</a>. The old request stays in <strong>Repaired</strong> as your history.</p><p>Corrective requests never create a copy.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the repeating request assigned to someone. The next activity goes to the <strong>Responsible</strong> person, so an empty field leaves the new job without an owner.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>A scheduled date makes the request appear on the <a href="./../calendar/maintenance-calendar.html">Maintenance calendar</a>. You see each month&#39;s job ahead of time.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Maintenance requests</a></li><li><a href="./create-request.html">Create a maintenance request</a></li><li><a href="./process-request.html">Process a request</a></li><li><a href="./../setup/stages.html">Stages</a></li></ul>',7))])}const _=s(l,[["render",h]]);export{v as __pageData,_ as default};
